source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    points = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != background:
                points.setdefault(v, []).append((r, c))
    for color, cells in points.items():
        cellset = set(cells)
        pairs = []
        for r, c in cells:
            for dr, dc in ((1, 1), (1, -1)):
                q = (r + dr, c + dc)
                if q in cellset:
                    pairs.append(((r, c), q))
        if not pairs:
            continue
        # Choose the exposed end of the diagonal segment; it points away from
        # the compact multicolor figure.
        a, b = pairs[0]
        def occupied_neighbors(p):
            r, c = p
            return sum(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] != background
                       for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
        ca, cb = occupied_neighbors(a), occupied_neighbors(b)
        if ca < cb:
            tip, prev = a, b
        elif cb < ca:
            tip, prev = b, a
        else:
            # In a tie, use the endpoint farther from the other foreground cells.
            def other_count(p):
                r,c=p
                return sum(max(abs(r-x), abs(c-y)) <= 1 for x,y in cells if (x,y) != p)
            if other_count(a) <= other_count(b):
                tip, prev = a, b
            else:
                tip, prev = b, a
        dr, dc = tip[0]-prev[0], tip[1]-prev[1]
        r, c = tip[0]+dr, tip[1]+dc
        while 0 <= r < h and 0 <= c < w and out[r][c] == background:
            out[r][c] = color
            r, c = r+dr, c+dc
    return out
'''
